contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address token, uint256 rewardAmount) public {
        require(rewardAmount > 0);
        // fresh state: token not yet added
        bool firstAddReverted;
        try c.addReward(token) { firstAddReverted = false; } catch { firstAddReverted = true; }
        assert(!firstAddReverted);
        // rule: after addReward, periodFinish == block.timestamp and lastUpdateTime set
        assert(c.rewardPeriodFinish(token) == uint40(block.timestamp));
        // second add for same token must revert ("exists")
        bool secondAddReverted;
        try c.addReward(token) { secondAddReverted = false; } catch { secondAddReverted = true; }
        assert(secondAddReverted);
        // token now known: notifyRewardAmount by distributor (owner default == this contract) must not revert
        c.setRewardDistributor(address(this));
        c.notifyRewardAmount(token, rewardAmount);
        assert(c.rewardPeriodFinish(token) == uint40(block.timestamp + (86400 * 7)));
    }
    receive() external payable {}
}

